Here is the commit message:
Bluetooth: hci_ll: Fix firmware leak on error path

Smatch reports:

drivers/bluetooth/hci_ll.c:587 download_firmware() warn:
'fw' from request_firmware() not released on lines: 544.

In download_firmware(), if request_firmware() succeeds but the returned
firmware content is invalid (no data or zero size), the function returns
without releasing the firmware, resulting in a resource leak.

Fix this by calling release_firmware() before returning when
request_firmware() succeeded but the firmware content is invalid.

Fixes: 371805522f87 ("bluetooth: hci_uart: add LL protocol serdev driver support")
Reviewed-by: Paul Menzel <pmenzel@molgen.mpg.de>
Signed-off-by: Anas Iqbal <mohd.abd.6602@gmail.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
In the `download_firmware()` function, when `request_firmware()` succeeds (returns 0) but the retrieved firmware is invalid (no data or zero size), the function returns an error without calling `release_firmware()` to free the firmware resource, leading to a memory leak.

Here is the patch:
  */
 static int download_firmware(struct ll_device *lldev)
 {
 	unsigned short chip, min_ver, maj_ver;
 	int version, err, len;
 	unsigned char *ptr, *action_ptr;
 	unsigned char bts_scr_name[40];	/* 40 char long bts scr name? */
 	const struct firmware *fw;
 	struct hci_command *cmd;

 	version = read_local_version(lldev->hu.hdev);
 	if (version < 0)
 		return version;

 	chip = (version & 0x7C00) >> 10;
 	min_ver = (version & 0x007F);
 	maj_ver = (version & 0x0380) >> 7;
 	if (version & 0x8000)
 		maj_ver |= 0x0008;

 	snprintf(bts_scr_name, sizeof(bts_scr_name),
 		 "ti-connectivity/TIInit_%d.%d.%d.bts",
 		 chip, maj_ver, min_ver);

 	err = request_firmware(&fw, bts_scr_name, &lldev->serdev->dev);
 	if (err || !fw->data || !fw->size) {
 		bt_dev_err(lldev->hu.hdev, "request_firmware failed(errno %d) for %s",
 			   err, bts_scr_name);
+		if (!err)
+			release_firmware(fw);
 		return -EINVAL;
 	}
 	ptr = (void *)fw->data;
 	len = fw->size;
 	/* bts_header to remove out magic number and
 	 * version
 	 */
 	ptr += sizeof(struct bts_header);
 	len -= sizeof(struct bts_header);

 	while (len > 0 && ptr) {
 		bt_dev_dbg(lldev->hu.hdev, " action size %d, type %d ",
 			   ((struct bts_action *)ptr)->size,
 			   ((struct bts_action *)ptr)->type);

 		action_ptr = &(((struct bts_action *)ptr)->data[0]);

 		switch (((struct bts_action *)ptr)->type) {
 		case ACTION_SEND_COMMAND:	/* action send */
 			bt_dev_dbg(lldev->hu.hdev, "S");
 			cmd = (struct hci_command *)action_ptr;
 			err = send_command_from_firmware(lldev, cmd);
 			if (err)
 				goto out_rel_fw;
 			break;
 		case ACTION_WAIT_EVENT:  /* wait */
 			/* no need to wait as command was synchronous */
 			bt_dev_dbg(lldev->hu.hdev, "W");
 			break;
 		case ACTION_DELAY:	/* sleep */
 			bt_dev_info(lldev->hu.hdev, "sleep command in scr");
 			msleep(((struct bts_action_delay *)action_ptr)->msec);
 			break;
 		}
 		len -= (sizeof(struct bts_action) +
 			((struct bts_action *)ptr)->size);
 		ptr += sizeof(struct bts_action) +
 			((struct bts_action *)ptr)->size;
 	}

 out_rel_fw:
 	/* fw download complete */
 	release_firmware(fw);
 	return err;
 }



